-- BAB 12: Sandi Morse (Komunikasi)
-- ==========================================
(12, 'Kata "Sandi" berasal dari bahasa Sanskerta, yang memiliki arti...', '["A. -", "B. Rahasia", "C. -", "D. -"]', 'B. Rahasia'),
(12, 'Fungsi utama mempelajari sandi dalam kegiatan kepramukaan adalah untuk...', '["A. -", "B. Melatih daya ingat, kecerdasan, dan ketelitian", "C. -", "D. -"]', 'B. Melatih daya ingat, kecerdasan, dan ketelitian'),
(12, 'Penemu sistem telegraf dan kode Morse adalah seorang seniman dan penemu asal Amerika yang bernama...', '["A. -", "B. Samuel F.B. Morse", "C. -", "D. -"]', 'B. Samuel F.B. Morse'),
(12, 'Kode Morse pertama kali ditemukan dan digunakan secara praktis pada tahun...', '["A. 1837", "B. -", "C. -", "D. -"]', 'A. 1837'),
(12, 'Dalam standar internasional, perbandingan durasi waktu antara bunyi/simbol "titik" dan "garis" pada sandi Morse adalah...', '["A. -", "B. 1 : 3", "C. -", "D. -"]', 'B. 1 : 3'),
(12, 'Huruf yang direpresentasikan dengan satu titik (.) dalam sandi Morse adalah...', '["A. -", "B. E", "C. -", "D. -"]', 'B. E'),
(12, 'Huruf yang direpresentasikan dengan satu garis (-) dalam sandi Morse adalah...', '["A. -", "B. -", "C. T", "D. -"]', 'C. T'),
(12, 'Kode Morse untuk huruf "A" adalah...', '["A. .-", "B. -", "C. -", "D. -"]', 'A. .-'),
(12, 'Kode Morse untuk huruf "B" adalah...', '["A. -...", "B. -", "C. -", "D. -"]', 'A. -...'),
(12, 'Sinyal marabahaya darurat atau minta tolong standar internasional (SOS) dalam sandi Morse ditulis dengan...', '["A. -", "B. ... --- ...", "C. -", "D. -"]', 'B. ... --- ...'),
(12, 'Kode Morse (...--) melambangkan angka...', '["A. -", "B. -", "C. 3", "D. -"]', 'C. 3'),
(12, 'Kode Morse (---..) melambangkan angka...', '["A. -", "B. -", "C. 8", "D. -"]', 'C. 8'),
(12, 'Kode Morse (----.) melambangkan angka...', '["A. -", "B. -", "C. 9", "D. -"]', 'C. 9'),
(12, 'Tanda pemisah antar kata saat menulis sandi Morse di atas kertas biasanya menggunakan tanda...', '["A. -", "B. Garis miring ganda (//)", "C. -", "D. -"]', 'B. Garis miring ganda (//)'),
(12, 'Dalam pengiriman pesan Morse, tanda untuk memulai panggilan atau "Attention" biasanya menggunakan kode...', '["A. -.-.-.", "B. -", "C. -", "D. -"]', 'A. -.-.-.'),
(12, 'Isyarat bahwa "Pesan Selesai" (End of Message) dalam pengiriman Morse ditandai dengan kode gabungan huruf AR, yaitu...', '["A. .-.-.", "B. -", "C. -", "D. -"]', 'A. .-.-.'),
(12, 'Jika pengirim melakukan kesalahan saat mengirim sandi Morse, ia memberikan isyarat salah (E 8 kali) yang berbunyi...', '["A. -", "B. ........", "C. -", "D. -"]', 'B. ........'),
(12, 'Huruf yang secara kode berlawanan dengan A (.-) adalah N, yaitu...', '["A. -.", "B. -", "C. -", "D. -"]', 'A. -.'),
(12, 'Huruf "O" dalam sandi Morse terdiri dari...', '["A. Tiga garis (---)", "B. -", "C. -", "D. -"]', 'A. Tiga garis (---)'),
(12, 'Huruf "S" dalam sandi Morse terdiri dari...', '["A. Tiga titik (...)", "B. -", "C. -", "D. -"]', 'A. Tiga titik (...)'),
(12, 'Gabungan huruf S dan O membentuk kata SOS, yang secara universal berarti isyarat...', '["A. -", "B. Darurat / Marabahaya", "C. -", "D. -"]', 'B. Darurat / Marabahaya'),
(12, 'Huruf "I" dalam sandi Morse terdiri dari...', '["A. -", "B. -", "C. Dua titik (..)", "D. -"]', 'C. Dua titik (..)'),
(12, 'Huruf "M" dalam sandi Morse terdiri dari...', '["A. -", "B. Dua garis (--)", "C. -", "D. -"]', 'B. Dua garis (--)'),
(12, 'Huruf "C" dalam sandi Morse dituliskan dengan kode...', '["A. -.-.", "B. -", "C. -", "D. -"]', 'A. -.-.'),
(12, 'Huruf "D" dalam sandi Morse dituliskan dengan kode...', '["A. -", "B. -..", "C. -", "D. -"]', 'B. -..'),
(12, 'Berlawanan dengan huruf D (-..), huruf "U" dalam sandi morse adalah...', '["A. ..-", "B. -", "C. -", "D. -"]', 'A. ..-'),
(12, 'Huruf "F" dalam sandi Morse adalah...', '["A. ..-.", "B. -", "C. -", "D. -"]', 'A. ..-.'),
(12, 'Huruf "G" dalam sandi Morse adalah...', '["A. -", "B. --.", "C. -", "D. -"]', 'B. --.'),
(12, 'Huruf "H" dalam sandi Morse adalah...', '["A. -", "B. -", "C. -", "D. ...."]', 'D. ....'),
(12, 'Huruf "J" dalam sandi Morse adalah...', '["A. -", "B. -", "C. .---", "D. -"]', 'C. .---'),
(12, 'Huruf "K" dalam sandi Morse adalah...', '["A. -.-", "B. -", "C. -", "D. -"]', 'A. -.-'),
(12, 'Huruf "L" dalam sandi Morse adalah...', '["A. -", "B. .-..", "C. -", "D. -"]', 'B. .-..'),
(12, 'Huruf "P" dalam sandi Morse adalah...', '["A. -", "B. -", "C. .--.", "D. -"]', 'C. .--.'),
(12, 'Huruf "Q" dalam sandi Morse adalah...', '["A. --.-", "B. -", "C. -", "D. -"]', 'A. --.-'),
(12, 'Huruf "R" dalam sandi Morse adalah...', '["A. -", "B. .-.", "C. -", "D. -"]', 'B. .-.'),
(12, 'Huruf "V" dalam sandi Morse adalah...', '["A. -", "B. -", "C. ...-", "D. -"]', 'C. ...-'),
(12, 'Huruf "W" dalam sandi Morse adalah...', '["A. .--", "B. -", "C. -", "D. -"]', 'A. .--'),
(12, 'Huruf "X" dalam sandi Morse adalah...', '["A. -", "B. -..-", "C. -", "D. -"]', 'B. -..-'),
(12, 'Huruf "Y" dalam sandi Morse adalah...', '["A. -", "B. -", "C. -.--", "D. -"]', 'C. -.--'),
(12, 'Huruf "Z" dalam sandi Morse adalah...', '["A. --..", "B. -", "C. -", "D. -"]', 'A. --..'),
(12, 'Angka 1 dalam sandi Morse ditulis dengan urutan...', '["A. -", "B. .----", "C. -", "D. -"]', 'B. .----'),
(12, 'Angka 5 dalam sandi Morse adalah...', '["A. -", "B. -", "C. .....", "D. -"]', 'C. .....'),
(12, 'Angka 0 dalam sandi Morse adalah...', '["A. -----", "B. -", "C. -", "D. -"]', 'A. -----'),
(12, 'Tanda koma (,) dalam tulisan Morse diwakili dengan gabungan...', '["A. -", "B. --..--", "C. -", "D. -"]', 'B. --..--'),
(12, 'Tanda tanya (?) dalam tulisan Morse diwakili dengan gabungan...', '["A. ..--..", "B. -", "C. -", "D. -"]', 'A. ..--..'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan pendek secara internasional mewakili...', '["A. Titik", "B. -", "C. -", "D. -"]', 'A. Titik'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan panjang yang keras mewakili...', '["A. -", "B. Garis", "C. -", "D. -"]', 'B. Garis'),
(12, 'Isyarat komunikasi "Tunggu" (AS) yang dikirimkan kepada lawan saat transmisi Morse adalah...', '["A. -", "B. -", "C. .-...", "D. -"]', 'C. .-...'),
(12, 'Isyarat "Mengerti / Pesan Diterima" (R) yang dikirimkan kembali oleh penerima pesan adalah...', '["A. .-.", "B. -", "C. -", "D. -"]', 'A. .-.'),
(12, 'Cara paling mudah dan umum yang diajarkan dalam pramuka untuk menghafal sandi Morse adalah metode pengelompokan huruf yang saling...', '["A. -", "B. Berlawanan / Berkebalikan (Contoh: A >< N)", "C. -", "D. -"]', 'B. Berlawanan / Berkebalikan (Contoh: A >< N)'),

-- ==========================================
-- BAB 15: Membaca Peta & Navigasi
-- ==========================================
(15, 'Gambar seluruh atau sebagian permukaan bumi yang diproyeksikan pada bidang datar dengan perbandingan skala tertentu disebut...', '["A. -", "B. Peta", "C. -", "D. -"]', 'B. Peta'),
(15, 'Jenis peta yang sangat penting bagi Pramuka karena menggambarkan tinggi rendahnya permukaan bumi (relief) secara detail adalah...', '["A. -", "B. Peta Topografi", "C. -", "D. -"]', 'B. Peta Topografi'),
(15, 'Kumpulan penjelasan tentang arti simbol-simbol dan warna yang terdapat pada peta disebut...', '["A. -", "B. -", "C. -", "D. Legenda Peta"]', 'D. Legenda Peta'),
(15, 'Angka yang menunjukkan perbandingan antara jarak di atas peta dengan jarak sebenarnya di lapangan disebut...', '["A. -", "B. -", "C. Skala", "D. -"]', 'C. Skala'),
(15, 'Peta dengan skala 1 : 25.000 berarti 1 cm pada peta mewakili jarak sebenarnya di lapangan sejauh...', '["A. -", "B. 250 meter", "C. -", "D. -"]', 'B. 250 meter'),
(15, 'Jika jarak antara titik A dan B di peta topografi (skala 1:50.000) adalah 4 cm, maka jarak sebenarnya di lapangan adalah...', '["A. -", "B. 2 kilometer", "C. -", "D. -"]', 'B. 2 kilometer'),
(15, 'Skala peta yang ditunjukkan dalam bentuk garis lurus yang terbagi menjadi beberapa ruas dengan ukuran satuan jarak tertentu disebut...', '["A. -", "B. -", "C. Skala Garis (Grafis)", "D. -"]', 'C. Skala Garis (Grafis)'),
(15, 'Garis khayal melingkar pada peta topografi yang menghubungkan titik-titik dengan ketinggian yang sama dari permukaan laut disebut...', '["A. -", "B. -", "C. Garis Kontur", "D. -"]', 'C. Garis Kontur'),
(15, 'Ciri khas utama dari garis kontur adalah jika jarak antar garisnya tergambar sangat rapat, hal itu menunjukkan bentuk medan yang...', '["A. -", "B. Curam / Terjal", "C. -", "D. -"]', 'B. Curam / Terjal'),
(15, 'Jika jarak antar garis kontur di peta terlihat renggang atau saling berjauhan, itu menandakan bentuk medan yang...', '["A. -", "B. -", "C. Landai / Datar", "D. -"]', 'C. Landai / Datar'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" terbalik yang menjorok ke arah ketinggian (menunjuk ke tempat yang lebih tinggi) menandakan bentang alam berupa...', '["A. -", "B. Lembah / Aliran Sungai", "C. -", "D. -"]', 'B. Lembah / Aliran Sungai'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" yang menjorok ke arah tempat yang lebih rendah menandakan bentang alam berupa...', '["A. -", "B. Punggungan (Sadel) / Punggung Bukit", "C. -", "D. -"]', 'B. Punggungan (Sadel) / Punggung Bukit'),
(15, 'Garis kontur yang tergambar berupa lingkaran-lingkaran kecil konsentris yang semakin mengecil di bagian tengah biasanya menandakan...', '["A. Puncak bukit / Gunung", "B. -", "C. -", "D. -"]', 'A. Puncak bukit / Gunung'),
(15, 'Jika ada garis kontur melingkar namun memiliki garis-garis rambut kecil (tick marks) yang mengarah ke bagian dalam lingkaran, itu menandakan...', '["A. -", "B. -", "C. Depresi / Kawah / Cekungan", "D. -"]', 'C. Depresi / Kawah / Cekungan'),
(15, 'Selisih ketinggian atau jarak vertikal antara satu garis kontur dengan garis kontur di sebelahnya disebut...', '["A. -", "B. Interval Kontur", "C. -", "D. -"]', 'B. Interval Kontur'),
(15, 'Garis kontur yang biasanya dicetak lebih tebal dan disertai angka penunjuk ketinggian untuk mempermudah pembacaan peta disebut...', '["A. -", "B. -", "C. Indeks Kontur", "D. -"]', 'C. Indeks Kontur'),
(15, 'Sistem garis kisi-kisi (grid) yang membagi peta menjadi kotak-kotak untuk menentukan posisi secara akurat dinamakan koordinat...', '["A. -", "B. -", "C. UTM (Universal Transverse Mercator)", "D. -"]', 'C. UTM (Universal Transverse Mercator)'),
(15, 'Garis vertikal (membujur dari bawah ke atas) pada sistem koordinat kotak (grid) peta yang angkanya dibaca pertama kali (dibaca ke arah Timur) disebut...', '["A. -", "B. Easting", "C. -", "D. -"]', 'B. Easting'),
(15, 'Garis horizontal (melintang dari kiri ke kanan) pada sistem koordinat grid peta yang angkanya dibaca kedua (dibaca ke arah Utara) disebut...', '["A. -", "B. Northing", "C. -", "D. -"]', 'B. Northing'),
(15, 'Aturan emas (golden rule) dalam membaca koordinat grid di atas peta topografi adalah...', '["A. -", "B. -", "C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)", "D. -"]', 'C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)'),
(15, 'Jika kita diminta menunjuk titik dengan koordinat 6 digit (contoh: 456 789), ini berarti tingkat ketelitian pencarian lokasi tersebut mencapai area seluas...', '["A. -", "B. 100 meter persegi", "C. -", "D. -"]', 'B. 100 meter persegi'),
(15, 'Arah Utara yang ditunjukkan oleh garis-garis grid vertikal lurus ke atas pada peta disebut...', '["A. -", "B. -", "C. Utara Peta (Grid North)", "D. -"]', 'C. Utara Peta (Grid North)'),
(15, 'Arah Utara yang mengarah tepat ke Kutub Utara bumi (poros rotasi) disebut...', '["A. -", "B. -", "C. Utara Sebenarnya (True North)", "D. -"]', 'C. Utara Sebenarnya (True North)'),
(15, 'Dalam legenda peta topografi standar, warna COKLAT umumnya digunakan untuk menggambarkan...', '["A. -", "B. -", "C. Garis ketinggian (Kontur) dan bentang alam darat", "D. -"]', 'C. Garis ketinggian (Kontur) dan bentang alam darat'),
(15, 'Warna HIJAU pada peta topografi selalu mengindikasikan adanya...', '["A. -", "B. Kawasan vegetasi / Hutan / Perkebunan", "C. -", "D. -"]', 'B. Kawasan vegetasi / Hutan / Perkebunan'),
(15, 'Warna BIRU pada peta digunakan secara universal untuk menyimbolkan unsur...', '["A. -", "B. -", "C. Hidrografi / Perairan (Sungai, danau, rawa, laut)", "D. -"]', 'C. Hidrografi / Perairan (Sungai, danau, rawa, laut)'),
(15, 'Warna MERAH pada peta topografi sering kali dikhususkan untuk menandakan unsur penting buatan manusia, yaitu...', '["A. -", "B. Jalan raya utama / aspal", "C. -", "D. -"]', 'B. Jalan raya utama / aspal'),
(15, 'Warna HITAM dalam peta biasanya digunakan untuk mencetak...', '["A. -", "B. -", "C. Simbol pemukiman, gedung, jalan setapak, dan tulisan", "D. -"]', 'C. Simbol pemukiman, gedung, jalan setapak, dan tulisan'),
(15, 'Simbol berupa titik hitam dengan bentuk segitiga atau lingkaran disertai angka (misal: ▲ 2100) di peta menunjukkan...', '["A. -", "B. Titik Triangulasi / Ketinggian mutlak (Spot Height)", "C. -", "D. -"]', 'B. Titik Triangulasi / Ketinggian mutlak (Spot Height)'),
(15, 'Tindakan menyamakan posisi arah Utara pada peta agar sejajar dengan arah Utara sebenarnya di lapangan (menggunakan kompas) disebut...', '["A. Orientasi Peta", "B. -", "C. -", "D. -"]', 'A. Orientasi Peta'),
(15, 'Syarat pertama yang harus dilakukan sebelum melakukan teknik navigasi Resection atau Intersection di lapangan adalah...', '["A. -", "B. Melakukan Orientasi Peta terlebih dahulu", "C. -", "D. -"]', 'B. Melakukan Orientasi Peta terlebih dahulu'),
(15, 'Teknik navigasi untuk menentukan titik koordinat posisi kita sendiri di atas peta, dengan cara membidik dua objek alam yang sudah diketahui di peta, disebut...', '["A. -", "B. -", "C. Resection", "D. -"]', 'C. Resection'),
(15, 'Teknik navigasi untuk mencari koordinat posisi objek lain (sasaran) yang belum diketahui di peta, dengan membidiknya dari dua titik stasiun yang berbeda, disebut...', '["A. -", "B. Intersection", "C. -", "D. -"]', 'B. Intersection'),
(15, 'Alat ukur sederhana berbentuk busur derajat berbentuk kotak persegi transparan yang digunakan untuk menghitung sudut dan koordinat langsung di atas peta disebut...', '["A. -", "B. -", "C. -", "D. Protractor (Busur Peta)"]', 'D. Protractor (Busur Peta)'),
(15, 'Alat mekanis kecil dengan roda bergerigi yang dijalankan menyusuri rute lengkung di peta (seperti sungai atau jalan berliku) untuk menghitung jarak disebut...', '["A. Curvimeter", "B. -", "C. -", "D. -"]', 'A. Curvimeter'),
(15, 'Penyimpangan sudut yang terjadi antara garis Utara Peta (Grid) dengan Utara Magnetis (Kompas) di suatu wilayah disebut...', '["A. Deklinasi Magnetis", "B. -", "C. -", "D. -"]', 'A. Deklinasi Magnetis'),
